sections.solution:
def add(a, b): return a + b
def subtract(a, b): return a - b
def multiply(a, b): return a * b
def divide(a, b):
    if b == 0: return "Error: cannot divide by zero"
    return a / b
def power(a, b): return a ** b

while True:
    num1 = float(input("First number: "))
    num2 = float(input("Second number: "))
    op   = input("Operation (+ - * / ^): ")

    if op == "+":   print("Result:", add(num1, num2))
    elif op == "-": print("Result:", subtract(num1, num2))
    elif op == "*": print("Result:", multiply(num1, num2))
    elif op == "/": print("Result:", divide(num1, num2))
    elif op == "^": print("Result:", power(num1, num2))
    else:           print("Unknown operation")

    again = input("Calculate again? (yes/no): ")
    if again != "yes":
        break

print("Goodbye!")
